package sbom

import (
	"path/filepath"
	"testing"
)

// Trimmed from files generated by pipenv 2026.10.4.

const pipfileSample = `[[source]]
url = "https://pypi.org/simple"
verify_ssl = true
name = "pypi"

[packages]
requests = "==2.19.0"
Jinja2 = {version = "==2.10", extras = ["i18n"]}
mylib = {path = "../mylib", editable = true}

[dev-packages]
pytest = "==7.0.0"
responses = "==0.10.6"

[docs]
Sphinx = "~=7.0"

[requires]
python_version = "3.10"

[scripts]
test = "pytest"
`

const pipfileLockSample = `{
    "_meta": {
        "hash": {"sha256": "5d3f5f0fabb2dd5bc1fb592de12f3eb94ae2ba5a675351b2ba0205dd48e602d0"},
        "pipfile-spec": 6,
        "requires": {"python_version": "3.10"},
        "sources": [{"name": "pypi", "url": "https://pypi.org/simple", "verify_ssl": true}]
    },
    "default": {
        "jinja2": {"extras": ["i18n"], "hashes": ["sha256:74c9"], "version": "==2.10"},
        "requests": {"hashes": ["sha256:421c"], "index": "pypi", "markers": "python_version >= '2.6'", "version": "==2.19.0"},
        "urllib3": {"hashes": ["sha256:a68a"], "version": "==1.23"},
        "mylib": {"editable": true, "path": "../mylib"},
        "gitpkg": {"git": "https://github.com/example/gitpkg.git", "ref": "abc123"}
    },
    "develop": {
        "Py": {"hashes": ["sha256:607c"], "version": "==1.11.0"},
        "pytest": {"hashes": ["sha256:42b9"], "index": "pypi", "version": "==7.0.0"},
        "requests": {"hashes": ["sha256:421c"], "index": "pypi", "version": "==2.19.0"},
        "responses": {"hashes": ["sha256:c654"], "index": "pypi", "version": "==0.10.6"},
        "urllib3": {"hashes": ["sha256:a68a"], "version": "==1.23"}
    },
    "docs": {
        "sphinx": {"hashes": ["sha256:16b6"], "version": "==7.0.0"},
        "urllib3": {"hashes": ["sha256:b1b1"], "version": "==2.0.0"}
    }
}`

func TestPipfileLockParser(t *testing.T) {
	root := writeFiles(t, map[string]string{"Pipfile": pipfileSample, "Pipfile.lock": pipfileLockSample})
	res, err := PipfileLockParser{}.Parse(filepath.Join(root, "Pipfile.lock"), "Pipfile.lock")
	if err != nil {
		t.Fatal(err)
	}
	checkPyComponents(t, res.Components, map[string][2]bool{
		"jinja2@2.10":      {true, false}, // declared with a non-normalized name
		"requests@2.19.0":  {true, false}, // in default and develop → production, once
		"urllib3@1.23":     {false, false},
		"py@1.11.0":        {false, true}, // name normalized
		"pytest@7.0.0":     {true, true},
		"responses@0.10.6": {true, true},
		"sphinx@7.0.0":     {true, true},  // custom category
		"urllib3@2.0.0":    {false, true}, // other version in a custom category
	})
	for _, c := range res.Components {
		if c.Manifest != "Pipfile.lock" || c.PURL != "pkg:pypi/"+c.Name+"@"+c.Version {
			t.Errorf("unexpected component %+v", c)
		}
	}
}

func TestPipfileLockParser_WithoutPipfile(t *testing.T) {
	root := writeFiles(t, map[string]string{"Pipfile.lock": pipfileLockSample})
	res, err := PipfileLockParser{}.Parse(filepath.Join(root, "Pipfile.lock"), "Pipfile.lock")
	if err != nil {
		t.Fatal(err)
	}
	for _, c := range res.Components {
		if c.Direct {
			t.Errorf("%s: direct is unknown without a Pipfile", c.Name)
		}
	}
	if len(res.Components) != 8 {
		t.Errorf("components = %d", len(res.Components))
	}
}

func TestPipfileLockParser_Invalid(t *testing.T) {
	for name, content := range map[string]string{
		"broken json":    `{"_meta": {`,
		"not a lock":     `{"default": {}}`,
		"bad categories": `{"_meta": {}, "default": ["requests"]}`,
	} {
		root := writeFiles(t, map[string]string{"Pipfile.lock": content})
		if _, err := (PipfileLockParser{}).Parse(filepath.Join(root, "Pipfile.lock"), "Pipfile.lock"); err == nil {
			t.Errorf("%s: expected error", name)
		}
	}
}

func TestParsePipfile(t *testing.T) {
	reqs, err := ParsePipfile([]byte(pipfileSample))
	if err != nil {
		t.Fatal(err)
	}
	type row struct {
		name, section, spec, extras string
		table, url, prod            bool
	}
	want := []row{
		{"jinja2", "packages", "==2.10", "[i18n]", true, false, true},
		{"mylib", "packages", "", "", true, true, true},
		{"requests", "packages", "==2.19.0", "", false, false, true},
		{"pytest", "dev-packages", "==7.0.0", "", false, false, false},
		{"responses", "dev-packages", "==0.10.6", "", false, false, false},
		{"sphinx", "docs", "~=7.0", "", false, false, false},
	}
	if len(reqs) != len(want) {
		t.Fatalf("got %d requirements: %+v", len(reqs), reqs)
	}
	for i, w := range want {
		r := reqs[i]
		got := row{r.Name, r.Section, r.Spec, r.Extras, r.Table, r.URL, r.Production()}
		if got != w || r.Kind != PyPipfile {
			t.Errorf("[%d] got %+v (kind %s), want %+v", i, got, r.Kind, w)
		}
	}

	m, _ := ParsePipfile([]byte("[packages]\nrequests = {version = \">=2\", markers = \"sys_platform != 'win32'\"}\n"))
	if len(m) != 1 || m[0].Marker != "; sys_platform != 'win32'" {
		t.Errorf("markers: %+v", m)
	}
	if _, err := ParsePipfile([]byte("[packages\n")); err == nil {
		t.Error("invalid TOML should fail")
	}
}

func TestPipenvLockCategory(t *testing.T) {
	for section, cat := range map[string]string{"packages": "default", "dev-packages": "develop", "docs": "docs"} {
		if got := PipenvLockCategory(section); got != cat {
			t.Errorf("%s → %s, want %s", section, got, cat)
		}
	}
}

func TestPipfileCheck(t *testing.T) {
	cases := map[string]struct {
		files map[string]string
		warn  bool
	}{
		"packages without lock": {map[string]string{"Pipfile": pipfileSample}, true},
		"with Pipfile.lock":     {map[string]string{"Pipfile": pipfileSample, "Pipfile.lock": "{}"}, false},
		"with requirements":     {map[string]string{"Pipfile": pipfileSample, "requirements.txt": ""}, false},
		"no packages":           {map[string]string{"Pipfile": "[requires]\npython_version = \"3.12\"\n"}, false},
	}
	for name, tc := range cases {
		root := writeFiles(t, tc.files)
		res, _ := PipfileCheck{}.Parse(filepath.Join(root, "Pipfile"), "Pipfile")
		if (len(res.Warnings) > 0) != tc.warn {
			t.Errorf("%s: warnings=%v want warn=%v", name, res.Warnings, tc.warn)
		}
	}
}

func TestPyprojectCheck_PipfileLockCounts(t *testing.T) {
	root := writeFiles(t, map[string]string{"pyproject.toml": poetryPyproject, "Pipfile.lock": "{}"})
	res, _ := PyprojectCheck{}.Parse(filepath.Join(root, "pyproject.toml"), "pyproject.toml")
	if len(res.Warnings) != 0 {
		t.Errorf("pyproject next to Pipfile.lock should not warn: %v", res.Warnings)
	}
}

func TestScanner_FindsPipenvProject(t *testing.T) {
	root := writeFiles(t, map[string]string{"api/Pipfile": pipfileSample, "api/Pipfile.lock": pipfileLockSample})
	res, err := NewScanner().Scan(root, nil)
	if err != nil {
		t.Fatal(err)
	}
	if len(res.Manifests) != 1 || res.Manifests[0] != filepath.Join("api", "Pipfile.lock") || len(res.Warnings) != 0 {
		t.Errorf("manifests=%v warnings=%v", res.Manifests, res.Warnings)
	}
}
